// LinkedIn — number validator: a restricted decimal first (reported title), then the full LeetCode 65 grammar.
// A hand-written state machine; no regex, no double.Parse.
public static class NumberValidator {
    // Optional sign, digits, optional '.', digits. At least one digit. No exponent, no spaces.
    public static bool IsDecimal(string s) {
        if (string.IsNullOrEmpty(s)) return false;
        int i = 0;
        if (s[i] == '+' || s[i] == '-') i++;
        int digits = 0; bool dot = false;
        for (; i < s.Length; i++) {
            if (char.IsAsciiDigit(s[i])) digits++;
            else if (s[i] == '.' && !dot) dot = true;
            else return false;
        }
        return digits > 0;
    }

    // Decimal or integer, optionally followed by e/E and a signed integer.
    public static bool IsNumber(string s) {
        if (string.IsNullOrEmpty(s)) return false;
        int e = s.IndexOfAny(new[] { 'e', 'E' });
        if (e < 0) return IsDecimal(s);
        return IsDecimal(s[..e]) && IsInteger(s[(e + 1)..]);
    }

    static bool IsInteger(string s) {
        if (string.IsNullOrEmpty(s)) return false;
        int i = s[0] == '+' || s[0] == '-' ? 1 : 0;
        if (i == s.Length) return false;
        for (; i < s.Length; i++) if (!char.IsAsciiDigit(s[i])) return false;
        return true;
    }
}
